using System.Text.Json; namespace MeshDriveSync;
public sealed class AppSettings { public string ServerUrl{get;set;}="";public string Username{get;set;}="";public string LocalFolder{get;set;}=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Mesh Drive");public List<string> SelectedFolders{get;set;}=new();public int IntervalSeconds{get;set;}=600;public int DebounceSeconds{get;set;}=10;public bool StartWithWindows{get;set;}=true;public bool SyncAll{get;set;}=false;public List<string> Ignore{get;set;}=new(){"*.tmp","~$*","Thumbs.db","*.meshsync-*"};public static string Data=>ProfileContext.Data;public static string Config=>ProfileContext.Config;public static string State=>ProfileContext.State;public static string Log=>ProfileContext.Log;public static AppSettings Load(){try{return JsonSerializer.Deserialize<AppSettings>(File.ReadAllText(Config))??new();}catch{return new();}}public void Save(){Directory.CreateDirectory(Data);File.WriteAllText(Config,JsonSerializer.Serialize(this,new JsonSerializerOptions{WriteIndented=true}));}}
public sealed class FileState{public string Hash{get;set;}="";public string? Etag{get;set;}} public sealed class StateStore{public Dictionary<string,FileState> Files{get;set;}=new(StringComparer.OrdinalIgnoreCase);public HashSet<string> Folders{get;set;}=new(StringComparer.OrdinalIgnoreCase);public static StateStore Load(){try{return JsonSerializer.Deserialize<StateStore>(File.ReadAllText(AppSettings.State))??new();}catch{return new();}}public void Save(){Directory.CreateDirectory(AppSettings.Data);File.WriteAllText(AppSettings.State,JsonSerializer.Serialize(this));}} public sealed record RemoteItem(string Path,bool Directory,DateTime? Modified,string? Etag);public sealed record ProgressInfo(string Status,string File,int Up,int Down,int Conflicts,int Errors,bool Error=false);
